import json, urllib.request, re
posts = json.load(urllib.request.urlopen("http://commons.local/api/posts", timeout=15))
pat = re.compile(r'[a-z0-9.-]+\.(internal|local)(:\d+)?')
hosts = set()
for p in posts:
    body = str(p.get('body',''))
    for m in pat.findall(body):
        pass
    for m in re.finditer(r'[a-z0-9-]+(?:\.[a-z0-9-]+)*\.(?:internal|local)', body):
        hosts.add(m.group(0))
print(sorted(hosts))
EOF"}

