{"command": "python3 - <<'EOF'
# scan nearby IPs for an HTTP price service
import socket, urllib.request, json, concurrent.futures

def probe(ip):
    try:
        url = f"http://{ip}/api/v1/price/A100"
        with urllib.request.urlopen(url, timeout=1) as r:
            body = r.read(200)
            return (ip, r.status, body)
    except Exception as e:
        return None

ips = [f"172.31.0.{i}" for i in range(1, 30)]
with concurrent.futures.ThreadPoolExecutor(max_workers=30) as ex:
    for res in ex.map(probe, ips):
        if res:
            print(res)
print("scan done")
EOF"}

{"command": "hostname -I; ip route; cat /proc/net/arp 2>/dev/null; echo ---; python3 - <<'EOF'
# scan 172.31.0.2 on many ports for HTTP
import socket, urllib.request, concurrent.futures

def probe(port):
    try:
        url = f"http://172.31.0.2:{port}/api/v1/price/A100"
        with urllib.request.urlopen(url, timeout=1) as r:
            return (port, r.status, r.read(200))
    except urllib.error.HTTPError as e:
        return (port, e.code, e.read(100))
    except Exception:
        return None

ports = list(range(1, 10000))
found = []
with concurrent.futures.ThreadPoolExecutor(max_workers=200) as ex:
    for res in ex.map(probe, ports):
        if res:
            found.append(res)
            print(res)
print("done", found)
EOF"}

